#nullable enable // autogenerated

using MVZ2.GameContent.Enemies;
using MVZ2.Vanilla.Detections;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Detections
{
    public class AxolotlSuitPilotDetector : Detector
    {
        public AxolotlSuitPilotDetector(bool canDetectInvisible)
        {
            this.canDetectInvisible = canDetectInvisible;
        }
        protected override Bounds GetDetectionBounds(Entity self)
        {
            return self.GetBounds();
        }
        public override bool ValidateTarget(DetectionParams self, Entity target)
        {
            if (!target.IsOnGround)
                return false;
            if (!AxolotlSuit.IsEmpty(target))
                return false;
            return base.ValidateTarget(self, target);
        }
    }
}
